  f4_t: { en: 'Where to look first (screening)', fr: 'Où regarder en premier (présélection)', rw: 'Aho twahera (gutoranya)' },
  f4: { en: '%s score highest at the default weights: drier seasons, few irrigated plots, much farmland. A shortlist for field checks, not an investment decision.', fr: '%s obtiennent le score le plus élevé aux poids par défaut. Une liste pour des vérifications sur le terrain, pas une décision d’investissement.', rw: "%s ni two dufite amanota menshi ku buremere busanzwe. Ni urutonde rwo kugenzura ku butaka, si icyemezo cy'ishoramari." },
  m_season_c: { en: 'In the dry Season C, between %s and %s of plots are irrigated, against about %s in the main seasons.', fr: 'En saison sèche C, entre %s et %s des parcelles sont irriguées, contre environ %s en saisons principales.', rw: 'Mu gihembwe C cy’izuba, hagati ya %s na %s by’imirima biruhirwa, naho hafi %s mu bihembwe bikuru.' },
  d_need_sub: { en: 'Normal rain %s mm per main season · %s dry seasons since 2016', fr: 'Pluie normale %s mm par saison principale · %s saisons sèches depuis 2016', rw: 'Imvura isanzwe %s mm ku gihembwe · ibihembwe %s byumye kuva 2016' },
  d_area_sub: { en: 'cultivated land, average per main season (A and B farm the same land)', fr: 'terres cultivées, moyenne par saison principale (A et B cultivent les mêmes terres)', rw: 'ubutaka buhingwa, impuzandengo ku gihembwe (A na B bihinga ubutaka bumwe)' },
  profile_rank: { en: 'Screening rank #%s at default weights (%s)', fr: 'Rang de présélection n° %s aux poids par défaut (%s)', rw: 'Umwanya wa %s ku buremere busanzwe (%s)' },
  d_score_sub: { en: 'Screening rank #%s at default weights (%s to %s across 1,000 weight sets)', fr: 'Rang n° %s aux poids par défaut (%s à %s sur 1 000 jeux de poids)', rw: 'Umwanya wa %s (hagati ya %s na %s)' },
