  n_note: { en: "Figures as published in NISR’s Seasonal Agricultural Survey tables. A change between seasons is reported, not explained.", fr: "Chiffres tels que publiés dans les tableaux de l’Enquête agricole saisonnière du NISR. Un écart entre saisons est rapporté, pas expliqué.", rw: "Imibare uko yatangajwe mu mbonerahamwe z'ubushakashatsi bw'ibihembwe by'ubuhinzi bwa NISR. Impinduka hagati y'ibihembwe iravugwa, ntisobanurwa." },
  our_note: { en: "Our analysis uses the survey microdata. It shows associations, not causes, and is not an official NISR statistic.", fr: "Notre analyse utilise les microdonnées. Elle montre des associations, pas des causes, et n’est pas une statistique officielle du NISR.", rw: "Isesengura ryacu rikoresha amakuru y'ibanze. Ryerekana isano, si impamvu, kandi si imibare yemewe ya NISR." },
  pub_no_sum: { en: "NISR publishes no figure for several districts together, so none is computed here.", fr: "Le NISR ne publie pas de chiffre pour plusieurs districts ensemble ; aucun n’est calculé ici.", rw: "NISR ntitangaza umubare w'uturere twinshi hamwe, bityo nta wubarwa hano." },
  dl_pub_csv: { en: "Download these NISR figures with their table and cell (CSV)", fr: "Télécharger ces chiffres du NISR avec tableau et cellule (CSV)", rw: "Kuramo iyi mibare ya NISR n'imbonerahamwe n'akazu (CSV)" },
